#include <iostream>
#include <assert.h>
#include <cstdlib>
#include <cstdio>
#include <cstring>
using namespace std;
const int N = 100005;
char str[N];
int main() {

    int n;
    cin >> n;
    cin >> str;
    assert(n == strlen(str));

    int ans = 0;
    for (int i = 0; i < n; i ++) {
        if (str[i] >= 'a' && str[i] <= 'z')
            ans += str[i] - 'a' + 1;
        else if (str[i] >= 'A' && str[i] <= 'Z')
            ans -= str[i];
        else
            assert(false);
    }
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 1010;
int a[N];
int main(){
    int n;
    cin >> n;
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    int ans=0;
    for(int i=1;i<=n;i++){
        for(int j=i+1;j<=n;j++){
            int m = a[i] + a[j];
            int t = sqrt(m + 1e-7);
            if(t * t == m)
                ans++;
        }
    }
    cout<<ans<<"\n";
}
